"""Политика повторов упавших заданий."""

from __future__ import annotations

import math
import random
from dataclasses import dataclass

from .errors import ConfigError, PermanentJobError


@dataclass(frozen=True)
class RetryPolicy:
    """Политика повторов с экспоненциальной задержкой.

    ``max_attempts`` — всего попыток, включая первую (1 = без повторов, но с dead-letter).
    ``non_retryable`` — классы исключений (с наследниками), после которых повтор не делается.
    """

    max_attempts: int = 3
    base_delay: float = 1.0
    factor: float = 2.0
    max_delay: float = 60.0
    jitter: float = 0.0
    non_retryable: tuple[type[BaseException], ...] = ()

    def __post_init__(self) -> None:
        if isinstance(self.max_attempts, bool) or not isinstance(self.max_attempts, int):
            raise ConfigError("max_attempts must be an integer")
        if self.max_attempts < 1:
            raise ConfigError("max_attempts must be at least 1")
        if not self.base_delay >= 0:
            raise ConfigError("base_delay must be non-negative")
        if not self.factor >= 1:
            raise ConfigError("factor must be at least 1")
        if not self.max_delay >= self.base_delay:
            raise ConfigError("max_delay must not be less than base_delay")
        if not 0 <= self.jitter <= 1:
            raise ConfigError("jitter must be between 0 and 1")
        try:
            items = tuple(self.non_retryable)
        except TypeError:
            raise ConfigError("non_retryable must be a sequence of exception classes") from None
        for item in items:
            if not (isinstance(item, type) and issubclass(item, BaseException)):
                raise ConfigError(f"non_retryable item {item!r} is not an exception class")
        object.__setattr__(self, "non_retryable", items)

    def delay_for(self, attempt: int, rng: random.Random | None = None) -> float:
        """Задержка перед следующей попыткой, если упала попытка номер ``attempt`` (с 1)."""
        if isinstance(attempt, bool) or not isinstance(attempt, int) or attempt < 1:
            raise ConfigError("attempt must be an integer >= 1")
        if self.base_delay == 0:
            delay = 0.0
        else:
            try:
                delay = min(self.base_delay * float(self.factor) ** (attempt - 1), self.max_delay)
            except OverflowError:
                delay = float(self.max_delay)
            if math.isnan(delay):  # защитная ветка (inf * 0 и т.п.)
                delay = float(self.max_delay)
        if self.jitter > 0:
            rng = rng if rng is not None else random
            delay *= rng.uniform(1 - self.jitter, 1 + self.jitter)
        return delay

    def is_retryable(self, exc: BaseException) -> bool:
        if isinstance(exc, PermanentJobError):
            return False
        return not (self.non_retryable and isinstance(exc, self.non_retryable))

    @property
    def label(self) -> str:
        """Человекочитаемое название для отчётов."""
        return _LABELS[self]

    @property
    def is_terminal(self) -> bool:
        """Задание в этом статусе больше не будет выполняться воркером."""
        return self in _TERMINAL


_LABELS: dict[JobStatus, str] = {
    JobStatus.PENDING: "В очереди",
    JobStatus.RUNNING: "Выполняется",
    JobStatus.SUCCEEDED: "Выполнено",
    JobStatus.FAILED: "Ошибка",
    JobStatus.CANCELLED: "Отменено",
    JobStatus.RETRY_SCHEDULED: "Ожидает повтора",
    JobStatus.DEAD_LETTERED: "В dead-letter",
}

_TERMINAL: frozenset[JobStatus] = frozenset(
    {JobStatus.SUCCEEDED, JobStatus.FAILED, JobStatus.CANCELLED}
)


